1651 | uint2tenbytefloat (uint32_t num, uint8_t *bytes)
1652 | {	uint32_t mask = 0x40000000 ;
1653 | 	int	count ;
1654 | 
1655 | 	if (num <= 1)
1656 | 	{	bytes [0] = 0x3F ;
1657 | 		bytes [1] = 0xFF ;
1658 | 		bytes [2] = 0x80 ;
1659 | 		return ;
1660 | 		} ;
