1663 | 
1664 | 	if (num >= mask)
1665 | 	{	bytes [1] = 0x1D ;
1666 | 		return ;
1667 | 		} ;
1668 | 
1669 | 	for (count = 0 ; count < 32 ; count ++)
1670 | 	{	if (num & mask)
1671 | 			break ;
1672 | 		mask >>= 1 ;
1673 | 		} ;
1674 | 
1675 | 	num = count < 31 ? num << (count + 1) : 0 ;
1676 | 	bytes [1] = 29 - count ;
1677 | 	bytes [2] = (num >> 24) & 0xFF ;
1678 | 	bytes [3] = (num >> 16) & 0xFF ;
1679 | 	bytes [4] = (num >> 8) & 0xFF ;
1680 | 	bytes [5] = num & 0xFF ;
